lidade":"BRASILEIRO (A)","naturalidade":"AQUIDABÃ","certidao_tipo":"NASCIMENTO","certidao_modelo":"ANTIGO","certidao_termo":"22.033","certidao_livro":"A-27","certidao_folha":"268V"},{"linha":33,"turma_origem":"ENF T-41 SEM","turno_origem":"NOITE","nome":"SAMUEL MATOS DE MORAES","cpf":"13218847532","email":"samuelmatos868@gmail.com","telefone":"(79) 99972-2890","data_nascimento":"2009-09-11","data_matricula":null,"endereco":"CONJ. JOÃO ALVES FILHO, RUA: A","bairro":"CENTRO","cidade":"AQUIDABÃ","uf":"SE","cep":"49790000","sexo":"M","rg":"13218847532","orgao_emissor":"SSP/SE","rg_uf_emissao":"SE","rg_data_emissao":"2025-01-20","tipo_documento":"CARTEIRA NACIONAL DE IDENTIFICAÇÃO","nome_mae":"EDNA MATOS DA SILVA","nome_pai":"EDIMILSON DE SOUZA MORAES","nacionalidade":"BRASILEIRO (A)","naturalidade":"CAPELA","certidao_tipo":"NASCIMENTO","certidao_modelo":"ANTIGO","certidao_termo":"25413","certidao_livro":"A-38","certidao_folha":"251"}]$source$::jsonb;
  v_turma public.turmas%rowtype;
  v_row record;
  v_parceiro_id uuid;
begin
  if jsonb_array_length(v_source) <> 32 then
    raise exception 'A importação T41 exige exatamente 32 registros de origem.';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_source) as s(cpf text)
    group by cpf
    having count(*) > 1
  ) then
    raise exception 'A origem T41 contém CPF duplicado.';
  end if;

  perform pg_advisory_xact_lock(hashtext('importacao-enf-t41-20260726'));

  select *
  into v_turma
  from public.turmas
  where codigo = 'ENF-T41-SEM-AQU'
  for update;

  if not found then
    raise exception 'Turma ENF-T41-SEM-AQU não encontrada.';
  end if;

  for v_row in
    select *
    from jsonb_to_recordset(v_source) as s(
      linha integer,
      turma_origem text,
      turno_origem text,
      nome text,
      cpf text,
      email text,
      telefone text,
      data_nascimento date,
      data_matricula date,
      endereco text,
      bairro text,
      cidade text,
      uf text,
      cep text,
      sexo text,
      rg text,
      orgao_emissor text,
      rg_uf_emissao text,
      rg_data_emissao date,
      tipo_documento text,
      nome_mae text,
      nome_pai text,
      nacionalidade text,
      naturalidade text,
      certidao_tipo text,
      certidao_modelo text,
      certidao_matricula text,
      certidao_termo text,
      certidao_livro text,
      certidao_folha text
    )
    order by linha
  loop
    v_parceiro_id := null;

    select p.id
    into v_parceiro_id
    from public.parceiros p
    where regexp_replace(coalesce(p.cpf_cnpj, ''), '\D', '', 'g') = v_row.cpf
    order by p.created_at, p.id
    limit 1;

    if v_parceiro_id is null then
      insert into public.parceiros (
        tipo, nome, cpf_cnpj, email, telefone,
        cep, endereco, bairro, cidade, uf, polo_id,
        status, observacao, data_nascimento, sexo,
        rg, orgao_emissor, rg_data_emissao, nacionalidade, naturalidade,
        nome_mae, nome_pai, rg_uf_emissao, tipo_documento,
        certidao_tipo, certidao_modelo, certidao_matricula,
        certidao_termo, certidao_livro, certidao_folha
      ) values (
        'Aluno', v_row.nome, v_row.cpf, v_row.email, v_row.telefone,
        v_row.cep, v_row.endereco, v_row.bairro, v_row.cidade, v_row.uf, v_turma.polo_id,
        'ATIVO',
        'Importado de turma 41.xls sem criação de usuário Auth, sem envio de e-mail e sem financeiro.',
        v_row.data_nascimento, v_row.sexo,
        v_row.rg, v_row.orgao_emissor, v_row.rg_data_emissao,
        coalesce(v_row.nacionalidade, 'BRASILEIRA'), v_row.naturalidade,
        v_row.nome_mae, v_row.nome_pai, v_row.rg_uf_emissao, v_row.tipo_documento,
        v_row.certidao_tipo, v_row.certidao_modelo, v_row.certidao_matricula,
        v_row.certidao_termo, v_row.certidao_livro, v_row.certidao_folha
      )
      returning id into v_parceiro_id;
    end if;

    if not exists (
      select 1 from public.matriculas m
      where m.aluno_id = v_parceiro_id and m.turma_id = v_turma.id
    ) then
      perform internal_academic.authorize_enrollment_upsert(
        v_parceiro_id, v_turma.id, 'PENDENTE'
      );

      insert into public.matriculas (
        aluno_id, turma_id, status, data_matricula,
        financeiro_herdado, gerar_cobranca_inicial,
        gerar_cobranca_futura, sincronizar_asaas
      ) values (
        v_parceiro_id, v_turma.id, 'PENDENTE',
        coalesce(v_row.data_matricula, v_turma.data_inicio)::timestamp
          at time zone 'America/Maceio',
        false, false, false, false
      );
    end if;
  end loop;

  update public.turmas t
  set vagas_totais = greatest(
    t.vagas_totais,
    (select count(*)::integer from public.matriculas m where m.turma_id = t.id)
  )
  where t.id = v_turma.id;
end;
